class Solution {
public:
    bool isMonotonic(vector<int>& A) {
        int prev = INT_MIN;
        auto comp = std::greater_equal<>();

        for(int x : A){
            // Any break will flip `comp` to get us correct sign.
            if(comp(x, prev))   comp = std::less_equal<>(); 

            if(!comp(prev,x)){
                return false;
            }
            prev = x;

        }

        return true;

    }
};
</solution>
